(()=>{
/* Bài 3 — Câu lệnh if, if–else (chuẩn mới 18/10/2026)
   Bối cảnh: quầy trà sữa của lớp tại Lễ hội Mùa Xuân. Tiết 1 = Chặng 1 (if, tiết thao giảng 28/10/2026 lớp 8A8),
   tiết 2 = Chặng 2 (if–else) và Chặng chứng chỉ. Mỗi chặng 6 tab (xem _Nguon_ChuanMoi/VAN_PHONG.md):
   Bối cảnh → Đoán rồi chạy → Kiểm chứng → Ghi nhớ → Luyện tập → Phản tư.
   Màn hình có số nhập: web và Programiz hiện lại số nhập sau câu dẫn rồi xuống dòng.
*/
"use strict";

const { cuPhap, scratch } = window.KIT;
const strip = code => window.CPP.stripComments(code);

/* ---------- đoạn code dùng xuyên suốt ---------- */
// Chặng 1: điều kiện viết sai mốc (> thay vì >=) — khách mua đúng 3 ly không được tặng.
const TOPPING = `#include <iostream>
using namespace std;
int main() {
    int soLy;
    cout << "Nhap so ly: ";
    cin >> soLy;
    if (soLy > 3) {
        cout << "Tang topping" << endl;
    }
    cout << "Cam on quy khach!";
    return 0;
}`;
const manTopping = (n, tang) => `Nhap so ly: ${n}\n${tang ? "Tang topping\n" : ""}Cam on quy khach!`;
const luaChonTopping = n => [manTopping(n, true), manTopping(n, false), `Nhap so ly: ${n}\nTang topping`];

// Chặng 2: if–else chọn quà theo mốc 5 ly.
const QUA = `#include <iostream>
using namespace std;
int main() {
    int soLy;
    cout << "Nhap so ly: ";
    cin >> soLy;
    if (soLy >= 5) {
        cout << "Tang banh" << endl;
    } else {
        cout << "Tang keo" << endl;
    }
    cout << "Cam on quy khach!";
    return 0;
}`;
const manQua = (n, qua) => `Nhap so ly: ${n}\n${qua}Cam on quy khach!`;
const luaChonQua = n => [manQua(n, "Tang banh\n"), manQua(n, "Tang keo\n"), manQua(n, "Tang banh\nTang keo\n")];

const PHI_GIAO_KHUNG = `#include <iostream>
using namespace std;
int main() {
    int tongTien;
    cout << "Nhap tong tien: ";
    cin >> tongTien;
    // Viet if - else o day

    cout << "Cam on quy khach!";
    return 0;
}`;
const HANG_KHUNG = `#include <iostream>
using namespace std;
int main() {
    int diem;
    cout << "Nhap diem: ";
    cin >> diem;
    // Viet if - else o day

    cout << "Cam on quy khach!";
    return 0;
}`;

const boiCanh = (big, text) => `<div class="scene-card"><div class="scene-big">${big}</div><p>${text}</p></div>`;
const cacTab = ten => `<div class="mission-row" style="grid-template-columns:repeat(auto-fit,minmax(96px,1fr))">
  ${ten.map((t, i) => `<div>${i + 1}<small>${t}</small></div>`).join("")}</div>`;
// 6 tab mỗi chặng (19/10): Dự đoán + Chạy thử gộp thành "Đoán rồi chạy" (đoán xong chạy ngay để so).
const sauTab = cacTab(["Bối cảnh", "Đoán rồi chạy", "Kiểm chứng", "Ghi nhớ", "Luyện tập", "Phản tư"]);
// Một lần "Đoán rồi chạy": chọn màn hình → bấm Chạy thử → so ngay. after: lần trước phải xong mới mở.
const doanQua = (id, lan, n, after, whyRight, why) => ({
  id, type: "doanchay", predict: true, icon: "🔮", after,
  title: `Lần ${lan} · Khách mua ${n === 5 ? "đúng " : ""}${n} ly`,
  prompt: `Khách nhập <code>${n}</code>. Máy sẽ in gì?`,
  code: QUA, input: String(n), options: luaChonQua(n), answer: manQua(n, n >= 5 ? "Tang banh\n" : "Tang keo\n"),
  run: runQua(n), whyRight, why });
const doanChay = (id, lan, n, after, whyRight, why) => ({
  id, type: "doanchay", predict: true, icon: "🔮", after,
  title: `Lần ${lan} · Khách mua ${n === 3 ? "đúng " : ""}${n} ly`,
  prompt: `Khách nhập <code>${n}</code>. Máy sẽ in gì?`,
  code: TOPPING, input: String(n), options: luaChonTopping(n), answer: manTopping(n, n > 3),
  run: runTopping(n), whyRight, why });
const bonBuoc = `<ol class="think-steps">
  <li><strong>Hiểu đề:</strong> nhập gì, in gì, quy tắc nói "từ", "trên" hay "dưới"?</li>
  <li><strong>Chọn biến:</strong> tên biến, kiểu <code>int</code>, ý nghĩa.</li>
  <li><strong>Thiết kế test case trước khi viết:</strong> một số dưới mốc, đúng mốc, trên mốc.</li>
  <li><strong>Viết → Chạy → So sánh → Sửa</strong> với từng test case.</li></ol>`;
const tuCham = "Chọn mức đúng với mình. Thầy dùng phần này để biết cần giảng thêm chỗ nào.";
const luuYIf = `<div class="note-card using-note"><strong>⚠️ Hai lỗi hay gặp với if</strong>
  <p>1. <strong>Không đặt dấu <code>;</code> ngay sau <code>if (…)</code>.</strong> Có dấu <code>;</code> thì khối <code>{ }</code> chạy với mọi khách.<br>
  2. <strong>So sánh bằng dùng <code>==</code></strong> (hai dấu bằng). Một dấu <code>=</code> là phép gán.</p></div>`;
const bangSoSanh = `<table class="test-table"><tr><th>Phép so sánh</th><th>Nghĩa là</th><th>Ví dụ (soLy = 3)</th><th>Kết quả</th></tr>
  <tr><td><code>&gt;</code></td><td>lớn hơn</td><td><code>soLy &gt; 3</code></td><td>sai</td></tr>
  <tr><td><code>&gt;=</code></td><td>lớn hơn hoặc bằng (“từ … trở lên”)</td><td><code>soLy &gt;= 3</code></td><td>đúng</td></tr>
  <tr><td><code>&lt;</code></td><td>nhỏ hơn (“dưới”)</td><td><code>soLy &lt; 3</code></td><td>sai</td></tr>
  <tr><td><code>&lt;=</code></td><td>nhỏ hơn hoặc bằng</td><td><code>soLy &lt;= 3</code></td><td>đúng</td></tr>
  <tr><td><code>==</code></td><td>bằng</td><td><code>soLy == 3</code></td><td>đúng</td></tr>
  <tr><td><code>!=</code></td><td>khác</td><td><code>soLy != 3</code></td><td>sai</td></tr></table>`;
const runTopping = n => ({
  label: `Chạy với ${n} ly`, code: TOPPING, input: String(n),
  steps: [[4, "", "khai báo soLy"], [5, "Nhap so ly: "], [6, `${n}\n`, `soLy = ${n}`],
    [7, "", `${n} > 3 → ${n > 3 ? "đúng" : "sai"}`, n > 3 ? "t" : "f"],
    ...(n > 3 ? [[8, "Tang topping\n"]] : []), [10, "Cam on quy khach!"], [11, "", "kết thúc"]],
  skip: n > 3 ? [] : [8]
});
const runQua = n => ({
  label: `Chạy với ${n} ly`, code: QUA, input: String(n),
  steps: [[4, "", "khai báo soLy"], [5, "Nhap so ly: "], [6, `${n}\n`, `soLy = ${n}`],
    [7, "", `${n} >= 5 → ${n >= 5 ? "đúng" : "sai"}`, n >= 5 ? "t" : "f"],
    ...(n >= 5 ? [[8, "Tang banh\n", "nhánh if"]] : [[9, "", "sang else"], [10, "Tang keo\n", "nhánh else"]]),
    [12, "Cam on quy khach!"], [13, "", "kết thúc"]],
  skip: n >= 5 ? [10] : [8]
});

window.LESSON = {
  id: "bai03",
  number: 3,
  title: "Câu lệnh if, if–else",
  story: "Quầy trà sữa Lễ hội Mùa Xuân",
  badge: { icon: "🧋", name: "Người giữ đúng khuyến mãi" },
  skills: ["Phép so sánh", "Câu lệnh if", "Khối lệnh { }", "if–else", "Kiểm thử đúng mốc", "Đọc lỗi logic"],
  certNote: "Nộp kèm: ảnh bài làm nhóm và bài cá nhân trên Programiz",

  errorTable: [
    ["Khách đúng mốc không được khuyến mãi", "Dùng <code>&gt;</code> trong khi quy tắc nói “từ … trở lên”", "Dùng <code>&gt;=</code>; luôn thử đúng số mốc"],
    ["Khối { } chạy với mọi khách", "Có dấu <code>;</code> ngay sau <code>if (…)</code>", "Xoá dấu <code>;</code> đứng sau dấu <code>)</code>"],
    ["Điều kiện bằng luôn đúng hoặc báo lỗi", "Viết <code>=</code> (gán) thay vì <code>==</code> (so sánh)", "So sánh bằng dùng <code>==</code>"],
    ["Lỗi cú pháp ở dòng else", "Viết điều kiện sau <code>else</code>", "<code>else</code> không có điều kiện: <code>} else {</code>"],
    ["Lời cảm ơn chỉ in cho một số khách", "Đặt lệnh cảm ơn bên trong khối <code>{ }</code>", "Đưa lệnh ra sau dấu <code>}</code> cuối cùng"],
    ["Máy không biết tên \"cout\"", "Thiếu <code>using namespace std;</code>", "Thêm ngay sau <code>#include &lt;iostream&gt;</code>"]
  ],

  steps: [
    /* ================= CHẶNG 1 · TIẾT 1 · if ================= */
    {
      kind: "stage", id: "stage-1", number: 1, nav: "Chặng 1",
      kicker: "CHẶNG 1 · TIẾT 1 · PHÉP SO SÁNH VÀ CÂU LỆNH if",
      title: "Tặng topping đúng quy tắc",
      bit: "Chào bạn! Mỗi tab là một phần. Làm xong thì bấm <strong>Tiếp</strong> ở cuối trang.",
      objectives: ["Viết điều kiện bằng phép so sánh, phân biệt > và >=", "Chỉ ra lệnh nào chạy khi điều kiện đúng, lệnh nào luôn chạy", "Kiểm thử chương trình bằng test case dưới, đúng và trên mốc"],
      flow: [
        { label: "Bối cảnh", title: "Khách mua đúng 3 ly mà không được tặng topping",
          html: boiCanh("Quy tắc của quầy: mua từ 3 ly trở lên được tặng topping.",
            "Hôm qua, khách mua đúng 3 ly nhưng máy không in “Tang topping”. Việc của bạn: tìm xem máy sai ở đâu, rồi sửa lại.") + sauTab },
        { label: "Đoán rồi chạy", title: "Đoán trước, rồi chạy để kiểm tra", tasks: ["c1-dc5", "c1-dc2", "c1-dc3"],
          code: TOPPING,
          html: `<p>Bên trái là chương trình của máy tính tiền. <code>if</code> nghĩa là <strong>nếu</strong>.</p>
            <p>Mỗi lần: <strong>chọn</strong> màn hình bạn đoán → bấm <strong>▶ Chạy thử</strong> → xem có khớp không. Đoán sai cũng không sao!</p>` },
        { label: "Kiểm chứng", title: "Khi nào lệnh trong { } được chạy?", tasks: ["c1-khoi", "c1-sau", "c1-moc"],
          code: TOPPING, focus: [7],
          html: `<p>Nhìn chương trình bên trái. Trả lời theo số dòng.</p>` },
        { label: "Ghi nhớ", title: "Câu lệnh if và phép so sánh",
          html: cuPhap({ ten: "CÂU LỆNH if", mau: ["if (‹điều kiện›) {", "    ‹các lệnh chạy khi điều kiện đúng›", "}", "‹lệnh phía sau: luôn chạy›"],
            phan: [["‹điều kiện›", "một phép so sánh, cho kết quả <strong>đúng</strong> hoặc <strong>sai</strong>"], ["{ }", "khối lệnh: chỉ chạy khi điều kiện đúng"]],
            quyTac: ["Điều kiện đúng: chạy khối <code>{ }</code>. Điều kiện sai: bỏ qua khối.", "Lệnh sau dấu <code>}</code> luôn chạy.", "“Từ 3 trở lên” viết <code>&gt;= 3</code>; “trên 3” viết <code>&gt; 3</code>."],
            viDu: `int soLy = 3;\nif (soLy >= 3) {\n    cout << "Tang topping" << endl;\n}\ncout << "Cam on quy khach!";`, man: "Tang topping\nCam on quy khach!" })
            + bangSoSanh + luuYIf
            + scratch("if <(so ly) > [2]> then\nsay [Tang topping]\nend\nsay [Cam on quy khach!]", "Giống khối <em>nếu … thì</em> trong Scratch.") },
        { label: "Luyện tập", title: "Sửa máy tính tiền và kiểm thử đúng mốc", tasks: ["c1-sua"],
          html: `<p>Làm theo <strong>4 bước của lập trình viên</strong>:</p>${bonBuoc}` },
        { label: "Phản tư", title: "Bạn đã chắc đến đâu?", tasks: ["c1-tucham"], stop: true,
          html: `<p>${tuCham}</p>`, bit: "Xong Chặng 1! Dừng lại và nhìn lên bảng." }
      ],
      challenges: [
        doanChay("c1-dc5", 1, 5, null, "5 > 3 đúng, nên máy chạy dòng 8.",
          "5 > 3 đúng, nên máy chạy dòng 8 (Tang topping), rồi chạy tiếp dòng 10."),
        doanChay("c1-dc2", 2, 2, "c1-dc5", "2 > 3 sai, nên máy bỏ qua dòng 8.",
          "2 > 3 sai, nên máy bỏ qua dòng 8. Dòng 10 nằm sau dấu } nên vẫn chạy."),
        doanChay("c1-dc3", 3, 3, "c1-dc2", "3 > 3 là sai, nên khách mua đúng 3 ly không được tặng. Lỗi nằm ở đây!",
          "3 > 3 là sai: 3 không lớn hơn 3. Vì vậy khách mua đúng 3 ly không được tặng. Lỗi của máy nằm ở đây!"),
        { id: "c1-khoi", type: "choice", icon: "🔍", title: "Dòng 8 chạy khi nào?",
          prompt: "Dòng 8 nằm trong khối <code>{ }</code> của <code>if</code>. Dòng 8 chạy khi nào?",
          options: [
            { text: "Khi điều kiện ở dòng 7 đúng" },
            { text: "Luôn chạy, với mọi số ly", why: "Lần chạy với 2 ly, dòng 8 bị mờ đi. Nhìn lại nhãn ở dòng 7." },
            { text: "Khi điều kiện ở dòng 7 sai", why: "Lần chạy với 5 ly: điều kiện đúng và dòng 8 sáng lên." }
          ],
          answer: "Khi điều kiện ở dòng 7 đúng", why: "Đúng. Điều kiện đúng thì máy chạy khối { }; sai thì bỏ qua cả khối." },
        { id: "c1-sau", type: "choice", icon: "🔍", title: "Dòng 10 chạy khi nào?",
          prompt: "Dòng 10 in lời cảm ơn. Dòng này chạy khi nào?",
          options: [
            { text: "Chỉ khi khách được tặng topping", why: "Lần chạy với 2 ly vẫn in Cam on quy khach!." },
            { text: "Luôn chạy, vì nằm sau dấu } của khối if" },
            { text: "Không bao giờ chạy", why: "Cả ba lần chạy đều in lời cảm ơn." }
          ],
          answer: "Luôn chạy, vì nằm sau dấu } của khối if", why: "Đúng. Lệnh đặt sau dấu } không phụ thuộc điều kiện." },
        { id: "c1-moc", type: "truefalse", icon: "✅", title: "Lỗi nằm ở mốc 3",
          prompt: "Chọn Đúng hoặc Sai cho từng câu.",
          items: [
            { text: "<code>3 &gt; 3</code> cho kết quả đúng.", answer: false, why: "3 không lớn hơn 3, nên 3 > 3 là sai." },
            { text: "<code>3 &gt;= 3</code> cho kết quả đúng.", answer: true },
            { text: "Quy tắc “từ 3 ly trở lên” tính cả khách mua đúng 3 ly.", answer: true },
            { text: "Thử với 5 và 2 ly là đủ để phát hiện lỗi của máy.", answer: false, why: "Với 5 và 2 máy đều chạy đúng; chỉ khi thử đúng 3 ly mới lộ lỗi. Luôn thử đúng số mốc." }
          ] },
        { id: "c1-sua", type: "code", icon: "🛠️", title: "Sửa máy tính tiền",
          prompt: "Sửa chương trình để khách mua từ 3 ly trở lên đều được tặng topping.",
          card: {
            boiCanh: "Quy tắc: mua từ 3 ly trở lên được tặng topping. Máy đang bỏ sót khách mua đúng 3 ly.",
            bien: [["int soLy;", "int", "số ly khách mua (số nguyên)"]],
            nhap: "In câu dẫn <code>Nhap so ly: </code> rồi <code>cin &gt;&gt; soLy;</code> (đã có sẵn).",
            xuLy: "Sửa điều kiện ở dòng 7 để tính cả đúng 3 ly. Giữ lời cảm ơn ở sau dấu <code>}</code>.",
            xuat: "Từ 3 ly: <code>Tang topping</code> rồi <code>Cam on quy khach!</code>. Dưới 3 ly: chỉ <code>Cam on quy khach!</code>.",
            tests: [
              { input: "2", expected: manTopping(2, false), why: "dưới mốc 3" },
              { input: "3", expected: manTopping(3, true), why: "<strong>đúng mốc 3</strong>: lỗi nằm ở đây" },
              { input: "4", expected: manTopping(4, true), why: "trên mốc 3" }
            ],
            dat: "Đúng cả 3 test case; giải thích được vì sao phải thử đúng 3 ly."
          },
          starter: TOPPING,
          hints: ["Quy tắc nói “từ 3 ly trở lên”: có tính đúng 3 ly không? Xem lại bảng phép so sánh.", "Ở dòng 7, đổi > thành >=. Giữ nguyên dòng 10 ở sau dấu }."] },
        { id: "c1-tucham", type: "self", icon: "🪞", title: "Phản tư Chặng 1",
          prompt: "Mỗi câu chọn một mức.",
          items: ["Mình giải thích được khi nào khối <code>{ }</code> của if được chạy.", "Mình phân biệt được <code>&gt;</code> và <code>&gt;=</code> khi gặp chữ “từ … trở lên”.", "Mình biết chọn test case dưới, đúng và trên mốc."] }
      ]
    },

    /* ================= CHẶNG 2 · TIẾT 2 · if–else ================= */
    {
      kind: "stage", id: "stage-2", number: 2, nav: "Chặng 2",
      kicker: "CHẶNG 2 · TIẾT 2 · CÂU LỆNH if–else",
      title: "Chọn một trong hai món quà",
      bit: "Chặng này máy phải chọn một trong hai việc. Làm lần lượt từng tab nhé.",
      objectives: ["Dùng if–else để chọn một trong hai nhánh", "Giải thích vì sao mỗi lần chạy chỉ một nhánh được thực hiện", "Thiết kế test case dưới, đúng và trên mốc cho if–else"],
      stopText: "Con hướng lên bảng để cả lớp trao đổi. Sau phần làm nhóm, thầy sẽ mở Chặng chứng chỉ.",
      flow: [
        { label: "Bối cảnh", title: "Khách nào cũng có quà",
          html: boiCanh("Quy tắc mới: mua từ 5 ly tặng bánh; dưới 5 ly tặng kẹo.",
            "Lần này máy phải chọn <strong>một trong hai</strong> món quà cho mỗi đơn. Việc của bạn: hiểu câu lệnh <code>if–else</code> rồi tự viết cho một quy tắc mới.") + sauTab },
        { label: "Đoán rồi chạy", title: "Khách nhận quà gì?", tasks: ["c2-dc4", "c2-dc5", "c2-dc6"],
          code: QUA,
          html: `<p>Bên trái là chương trình mới. <code>else</code> nghĩa là <strong>nếu không thì</strong>.</p>
            <p>Mỗi lần: <strong>chọn</strong> màn hình bạn đoán → bấm <strong>▶ Chạy thử</strong> → xem nhánh nào sáng lên.</p>` },
        { label: "Kiểm chứng", title: "Mỗi lần chạy đi nhánh nào?", tasks: ["c2-nhanh", "c2-else", "c2-mot"],
